/* P1-13 13i part 2b: an installed edition package's own scope-outs (its classes and its tests) come from its test hook. */
$editionIgnores = EditionTestHooks::archPresetIgnores();
array_push($bannedFunctionUsers, ...$editionIgnores['banned_functions']);

$laravelLegacy = array_map(fn ($l) => explode("\t", $l)[0], array_filter(file(__DIR__.'/laravel-preset-ignores.txt', FILE_IGNORE_NEW_LINES)));

arch('php preset')->preset()->php()->ignoring($bannedFunctionUsers);

arch('security preset')->preset()->security()->ignoring($bannedFunctionUsers);

/* The laravel preset is written for the stock App\\ layout: it forbids anything outside App\\Http / App\\Providers from using
 * App\\Http\\*, and bans controller helper methods. Module code (Juwri\\Modules, Juwri\\Core) legitimately uses the shared
 * App\\Http requests/middleware until those move into modules, and the legacy App\\Http\\Controllers carry many public helpers,
 * so both are scoped out of THIS preset only; the function bans (dd, env, exit, ...) still cover every namespace below. */
arch('laravel preset')->preset()->laravel()->ignoring(['Juwri\\Modules', 'Juwri\\Core', 'App\\Http\\Controllers', ...$editionIgnores['laravel'], ...$bannedFunctionUsers, ...$laravelLegacy]);

arch('no debugging, env() or exit outside config/bootstrap')
    ->expect(['dd', 'ddd', 'dump', 'env', 'exit', 'ray'])
    ->not->toBeUsed()
    ->ignoring($bannedFunctionUsers);
